    /**
     * Tests creating a new Competency.
     *
     * @return    Competency
     */
    public Competency testCreate() throws Throwable {
    Competency entity = null;

    LOGGER.info( "CompetencyTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Competency");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Competency" );

    try {
        entity = service.createCompetency( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getCompetencyId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Competency with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

