    /**
     * Tests getting all Competencys.
     *
     * @return    Collection
     */
    public List<Competency> testGetAll() throws Throwable {
    LOGGER.info( "CompetencyTest:testGetAll() - Retrieving Collection of Competencys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Competency : " );
    List<Competency> collection  = null;

    try {
        // call the static get method on the CompetencyService
        collection = service.getAllCompetency();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Competency currEntity  = null;
            Iterator<Competency> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCompetencyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

